export const Workflow = {
  get: "_dev.xsb/workflow/get",
  list: "_dev.xsb/workflow/list",
  update: "_dev.xsb/workflow/update",
  stop: "_dev.xsb/workflow/stop",
  pause: "_dev.xsb/workflow/pause",
  resume: "_dev.xsb/workflow/resume",
  rollback: "_dev.xsb/workflow/rollback",
  backend: "dev.xsb/backend",
  target: "dev.xsb/workflow-target",
} as const;

/** Portable skill instructions generated by the main agent, not a backend-native skill name. */
export type WorkflowSkill = { name: string; description: string; content: string };
/** Immutable identity of a reused task agent. Assignment inputs stay on NodeDef. */
export type NodeAgentConfig = { systemPrompt?: string; skills?: WorkflowSkill[] };
export type NodeDef = {
  node: string;
  kind: "task" | "end";
  prompt?: string;
  input: Record<string, unknown>;
  /** Markdown task and delivery requirements. Legacy nodes use prompt. */
  requirements?: string;
  /** The optional Markdown JSONL input on an entry task, before any assignment runs. */
  entryInput?: string;
  /** Schema for the assembled named inputs (fixed values and active edge bindings). */
  inputSchema?: object;
  model?: string;
  agent?: NodeAgentConfig;
  schema?: object;
  multi: boolean;
};
export type Edge = { from: string; to: string; case?: string; bind?: Record<string, string> };
export type WorkflowGraph = { format?: "markdown"; nodes: NodeDef[]; edges: Edge[] };
/** A node as a view shows it: its definition's name and kind, where its work stands, and who did it. */
export type WorkflowNodeView = {
  name: string;
  kind: NodeDef["kind"];
  status: string;
  paused: boolean;
  /** The user's interruption of it got to its agent and is not handled yet (its turn failed or stopped): it holds the node until resumed. */
  interrupted?: boolean;
  agentId?: string;
  sessionId?: string;
  target?: string;
  /** The current accepted graph delivery, including while a choice or additional assignment is pending. */
  deliveryId?: string;
  summary?: string;
  /** Markdown definition and the currently valid assignment/delivery, including its direct sources. */
  markdown?: {
    requirements?: string;
    entryInput?: string;
    input?: string;
    sources?: { node: string; delivery: string }[];
    output?: string;
    choice?: string;
  };
  /** Declared inputs and output, with the values and provenance of this version's assignment. */
  contract?: {
    goal?: string;
    inputSchema: object;
    schema?: object;
    fixedInput?: Record<string, unknown>;
    input?: Record<string, unknown>;
    inputSources?: Record<string, { node: string; delivery: string; pointer: string }>;
    result?: unknown;
    error?: string;
  };
  additionalResults?: { id: string; summary: string }[];
  controls?: { stop?: boolean; pause: boolean; resume: boolean; rollback?: boolean };
};

/**
 * A version that was active and was replaced: its graph and its nodes as they stood then. Kept to be looked at;
 * the conversations of its nodes can be read, not continued.
 */
export type WorkflowHistory = {
  version: string;
  retiredAt: string;
  format?: "markdown";
  /** Distinguishes historical executions of the same plan after rollback. */
  snapshot?: string;
  rollback?: boolean;
  nodes: WorkflowNodeView[];
  edges: Edge[];
};

export type WorkflowView = {
  /** Authoritative runtime state and actions; clients need not infer them from node labels. */
  state?: "empty" | "proposed" | "running" | "paused" | "completed";
  controls?: { stop?: boolean; pause: boolean; resume: boolean; rollback?: boolean };
  /** Earlier active versions, the latest first. */
  history?: WorkflowHistory[];
  sessionId: string;
  version?: string;
  format?: "markdown";
  candidate?: { version: string; graph: WorkflowGraph };
  edges: Edge[];
  paused: boolean;
  /** An interruption from the main conversation holds the whole graph until it is handled, or the workflow resumed. */
  interrupted?: boolean;
  error?: string;
  nodes: WorkflowNodeView[];
};
